import names from "./building-names.json";

// Generated by scripts/building-names.py from aoe4world/data (buildings/all.json).
// Icons live in public/building-icons/.
export type BuildingKind = "landmark" | "religious" | "technology" | "defense" | "military" | "economy" | "other";

export type BuildingInfo = { name: string; kind: BuildingKind; icon: string | null };

// JSON imports type tuples as string[], so the shape is asserted here.
const table = names as unknown as Record<string, [string, BuildingKind, string]>;

export function buildingInfo(pbgid: number): BuildingInfo {
  const entry = table[pbgid];
  if (!entry) return { name: `Building ${pbgid}`, kind: "other", icon: null };
  return { name: entry[0], kind: entry[1], icon: `/building-icons/${entry[2]}` };
}
